  ["6d:5270"] = "Hola, al habla\n{STRBUF}…\012¡Hola, {PLAYER}!\n¡Buenos días!{DONE}",
  ["6d:52a5"] = "Hola, al habla\n{STRBUF}…\012¡Hola, {PLAYER}!{DONE}",
  ["6d:52cc"] = "Hola, al habla\n{STRBUF}…\012¡Hola, {PLAYER}!\n¡Buenas noches!{DONE}",
  ["6d:5301"] = "¡{PLAYER}, buenos\ndías!\012Soy yo, {STRBUF}.\n¿Qué tal vas?{DONE}",
  ["6d:5335"] = "¡Hola, {PLAYER}!\012Soy yo, {STRBUF}.\n¿Qué tal vas?{DONE}",
  ["6d:535f"] = "¡{PLAYER}, buenas\nnoches!\012Soy yo, {STRBUF}.\n¿Qué tal vas?{DONE}",
  ["6d:5393"] = "¿Qué tal van tus\nPOKéMON?\012Mi {STRBUF}\nlo está haciendo\011mejor que nunca.\012¡Si seguimos así,\nseremos CAMPEONES\011POKéMON!{DONE}",
  ["6d:53f7"] = "Hola, soy\n{STRBUF}.\012Oh, {PLAYER}.\nBuenos días.{DONE}",
