  ["6d:5446"] = "Hola, soy\n{STRBUF}.\012Oh, {PLAYER}.\nBuenas noches.{DONE}",
  ["6d:5472"] = "¡Buenos días,\n{PLAYER}!\012Soy {STRBUF}.\n¿Dormías?{DONE}",
