  ["6d:54d4"] = "Hola, {PLAYER}.\nBuenas noches.\012Soy {STRBUF}.\012No estabas dur-\nmiendo, ¿verdad?{DONE}",
  ["6d:5510"] = "¿Eres del tipo de\npersona que va a\012menudo a los\nCENTROS POKéMON?\012Yo voy todos los\ndías. Cuidar de\012la salud de tus\nPOKéMON es uno de\012los principios\nbásicos de\011entrenar POKéMON.{DONE}",
  ["6d:55ae"] = "Hola, soy\n{STRBUF}…\012Oh, ¿{PLAYER}?\n¡Buenos días!{DONE}",
  ["6d:55da"] = "Hola, soy\n{STRBUF}…\012Oh, ¿{PLAYER}?\n¡Hola!{DONE}",
  ["6d:55fc"] = "Hola, soy\n{STRBUF}…\012Oh, ¿{PLAYER}?\n¡Buenas noches!{DONE}",
