  ["6d:5670"] = "Oh, ¿{PLAYER}?\012¡Genial! Sí, soy\nyo, {STRBUF}.{DONE}",
  ["6d:5694"] = "Tus POKéMON,\n¿aún se entrenan?\012Mi {STRBUF}\ntiene mucha\011energía.\012Cuando despega, no\nvuelve en un rato.{DONE}",
  ["6d:5702"] = "Hola, soy\n{STRBUF}…\012Oh. Hola, {PLAYER}.\n¿Qué pasa?{DONE}",
  ["6d:572e"] = "Hola, soy\n{STRBUF}…\012Oh, hola, {PLAYER}.\n¿Qué pasa?{DONE}",
  ["6d:575a"] = "Hola, soy\n{STRBUF}…\012Oh, hola, {PLAYER}.\n¿Qué pasa?{DONE}",
  ["6d:5786"] = "¡Qué lentitud! \n¡Date prisa y\011contesta!\012¡Soy yo, {STRBUF}!{DONE}",
  ["6d:57b7"] = "¡Qué lentitud! \n¡Date prisa y\011contesta!\012¡Soy yo, {STRBUF}!{DONE}",
  ["6d:57e8"] = "¡Qué lentitud! \n¡Date prisa y\011contesta!\012¡Soy yo, {STRBUF}!{DONE}",
  ["6d:5819"] = "Eh, ¿qué tal van\ntus POKéMON?\012¿Cómo? ¿Genial?\nYa veo…\012¿Qué? ¿Mis\nPOKéMON?\012¡Claro que lo\nestán haciendo\012bien! ¿A qué te\nrefieres?{DONE}",
  ["6d:589a"] = "¡Hola, soy\n{STRBUF}!\012Oh, ¿{PLAYER}?\n¿Qué tal estás?{DONE}",
