  ["6d:58ea"] = "¡Hola, soy\n{STRBUF}!\012Oh, ¿{PLAYER}?\n¿Qué tal estás?{DONE}",
  ["6d:5912"] = "¡Hola, {PLAYER}!\n¿Qué tal estás?\012Soy {STRBUF}.\n¿Tienes un minuto?{DONE}",
  ["6d:5948"] = "¡Hola, {PLAYER}!\n¿Qué tal estás?\012Soy {STRBUF}.\n¿Tienes un minuto?{DONE}",
  ["6d:597c"] = "¡Hola, {PLAYER}!\n¿Qué tal estás?\012Soy {STRBUF}.\n¿Tienes un minuto?{DONE}",
  ["6d:59b2"] = "¿Qué tal van tus\nPOKéMON?\012Mi {STRBUF}\nestá ansioso por\012luchar, como\nsiempre.\012Es el único que\ntengo. ¡Con él,\012llegaré a ser un\ngran entrenador!{DONE}",
  ["6d:5a3b"] = "¿Diga? Al habla\n{STRBUF}.\012¡Hola, {PLAYER}!\n¡Buenos días!{DONE}",
  ["6d:5a74"] = "¿Diga? Al habla\n{STRBUF}.\012¡Hola, {PLAYER}!{DONE}",
  ["6d:5a9f"] = "¿Hola? Al habla\n{STRBUF}.\012¡Hola, {PLAYER}!\n¡Buenas noches!{DONE}",
  ["6d:5ad8"] = "¡{PLAYER}, buenos\ndías!\012Soy yo, {STRBUF}.\n¿A que hace un día\011estupendo?{DONE}",
  ["6d:5b0b"] = "¡Hola, {PLAYER}!\012Soy yo, {STRBUF}.\n¿A que hace un día\011estupendo?{DONE}",
  ["6d:5b37"] = "¡Buenas noches,\n{PLAYER}!\012Soy yo, {STRBUF}.\n¿Estabas\011durmiendo?{DONE}",
  ["6d:5b68"] = "¿Qué tal están tus\nPOKéMON?\012Mis POKéMON tienen\ndemasiada energía.\012Puede llegar a ser\nun problema.\012De todos mis POKé-\nMON, {STRBUF} es\012el más difícil de\ncontrolar.\012Trabajar con él\ncansa mucho.{DONE}",
  ["6d:5c10"] = "¿Sí? Ah, {PLAYER}.\012Eres muy cortés\nal presentarte\012cuando llamas por\nteléfono.{DONE}",
  ["6d:5c63"] = "¿Sí? Ah, {PLAYER}.\012Eres muy cortés\nal presentarte\012cuando llamas por\nteléfono.{DONE}",
  ["6d:5cb6"] = "¿Sí? Ah, {PLAYER}.\012Eres muy cortés\nal presentarte\012cuando llamas por\nteléfono.{DONE}",
  ["6d:5d09"] = "Hola, soy el tío\n{STRBUF}.{DONE}",
  ["6d:5d21"] = "Hola, soy el tío\n{STRBUF}.{DONE}",
  ["6d:5d39"] = "Hola, soy el tío\n{STRBUF}.{DONE}",
  ["6d:5d51"] = "¿Estás cuidando\nbien de tus\012POKéMON? ¡Debes\ntratar bien a tus\011compañeros!{DONE}",
  ["6d:5d9f"] = "Hola. {STRBUF}\nal habla.\012Oh, {PLAYER}.\nBuenos días.{DONE}",
