  ["6d:5df8"] = "Hola. {STRBUF}\nal habla.\012Oh, {PLAYER}.\nBuenas noches.{DONE}",
  ["6d:5e25"] = "Buenos días,\n{PLAYER}.\012Soy {STRBUF}.\n¿Dormías?{DONE}",
  ["6d:5e59"] = "Hola, {PLAYER}.\nSoy {STRBUF}.\012¿Qué tal te van\nlas cosas?{DONE}",
  ["6d:5e8e"] = "Buenas noches,\n{PLAYER}.\012Soy {STRBUF}.\n¿Aún sin dormir?{DONE}",
  ["6d:5ebe"] = "Tenía algo de\ntiempo, así que\011pensé en llamarte.\012De todos modos,\n¿qué tal están tus\011POKéMON?\012Yo llevo a mi\n{STRBUF} al\012CENTRO POKéMON de\nCIUDAD MALVA todos\012los días, así que\nestá fantástico.\012¡Soy amiga de la\nrecepcionista!{DONE}",
  ["6d:5f7a"] = "Soy {STRBUF}, el\nMONTAÑERO.\012¡Ah, {PLAYER}!{DONE}",
